import React from 'react';

export default function Navbar({ email, onLogout }) {
  return (
    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '12px 18px', background: 'rgba(0,0,0,0.5)', color: '#fff' }}>
      <div style={{ fontWeight: '700', fontSize: 18 }}>BestOddsGH</div>
      <div style={{ display: 'flex', gap: 12, alignItems: 'center' }}>
        <div style={{ opacity: 0.9 }}>{email}</div>
        <button className="btn" onClick={onLogout}>Logout</button>
      </div>
    </div>
  );
}
